// Catálogo comercial do Pomin360. A base (nome, textos, passos, ícones e ferramentas substituídas) veio do
// app.js da página legada; o que é novo aqui é o "antes e depois" e o guia de demonstração (a antiga COLINHA).
// Regra: nada de número ou recurso que não esteja no catálogo, nos READMEs ou nas páginas oficiais do P360.

export type Categoria = 'IA & criação' | 'Gestão & inteligência' | 'Operação & execução' | 'Relacionamento';

export interface App {
  id: string; name: string; category: Categoria; icon: string; color: string; url: string;
  summary: string; description: string; audience: string; modules: string[];
  headline: [string, string]; steps: [string, string][]; chips: string[];
}

export interface Guia {
  pitch: string;                       // em uma frase, para abrir a demonstração
  antes: string[]; depois: string[];   // a diferença real quando o Pomin360 entra
  falas: string[];                     // o que dizer em cada passo da demonstração (mesma ordem de steps)
  descoberta: string[];                // perguntas para entender o cliente
  objecoes: [string, string][];        // o que o cliente costuma dizer e como responder
  prova?: [string, string];            // número de uso real, quando existe
}

export interface Tool { name: string; app: string; hex: string; svg: string }

